def list_subtitle_languages(url, **_extra):
    import json, os, datetime, time, re, urllib.parse, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_credential_id=None, error_code=None):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{_now()}|list_subtitle_languages|{random.random()}".encode("utf-8")).hexdigest()[:16],
            "endpoint": "list_subtitle_languages",
            "credential_id": used_credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now()
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    # Quota / rate enforcement if usage store exists
    def _enforce_limits():
        # Optional policy file: quotas.json
        quotas = _load("quotas.json")
        if isinstance(quotas, dict):
            rate = quotas.get("rate_limit_per_minute")
            daily = quotas.get("daily_quota")
        else:
            rate = None
            daily = None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        if rate is not None:
            try:
                rate_n = int(rate)
                if rate_n > 0:
                    cutoff = now - datetime.timedelta(seconds=60)
                    cnt = 0
                    for r in logs:
                        if r.get("endpoint") != "list_subtitle_languages":
                            continue
                        ts = r.get("created_at")
                        if not isinstance(ts, str):
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            cnt += 1
                    if cnt >= rate_n:
                        return _err("RATE_LIMIT", "Rate limit exceeded for subtitle discovery")
            except Exception:
                pass

        if daily is not None:
            try:
                daily_n = int(daily)
                if daily_n >= 0:
                    cutoff = now - datetime.timedelta(days=1)
                    cnt = 0
                    for r in logs:
                        if r.get("endpoint") != "list_subtitle_languages":
                            continue
                        ts = r.get("created_at")
                        if not isinstance(ts, str):
                            continue
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            cnt += 1
                    if cnt >= daily_n:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for subtitle discovery")
            except Exception:
                pass
        return None

    def _is_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _canonicalize(u):
        p = urllib.parse.urlparse(u.strip())
        scheme = p.scheme.lower()
        netloc = p.netloc.lower()
        # strip default ports
        if netloc.endswith(":80") and scheme == "http":
            netloc = netloc[:-3]
        if netloc.endswith(":443") and scheme == "https":
            netloc = netloc[:-4]
        # drop fragments; normalize query: keep but sort
        q = urllib.parse.parse_qsl(p.query, keep_blank_values=True)
        q.sort()
        query = urllib.parse.urlencode(q)
        path = re.sub(r"/{2,}", "/", p.path or "/")
        return urllib.parse.urlunparse((scheme, netloc, path, "", query, ""))

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", error_code=limit_err["error"]["code"])
        return limit_err

    if not _is_url(url):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `url` must be a valid http(s) URL.")

    canonical_url = _canonicalize(url)

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    subtitle_tracks = _load("subtitle_tracks.json")
    if not isinstance(subtitle_tracks, list):
        subtitle_tracks = []

    # Upsert by canonical_url
    now = _now()
    vid = None
    for v in videos:
        if isinstance(v, dict) and v.get("canonical_url") == canonical_url:
            vid = v
            break
    if vid is None:
        vid_id = "vid_" + hashlib.sha256(f"{canonical_url}".encode("utf-8")).hexdigest()[:16]
        vid = {
            "id": vid_id,
            "source_url": url,
            "canonical_url": canonical_url,
            "extractor": None,
            "extractor_video_id": None,
            "title": None,
            "duration_seconds": None,
            "webpage_url": None,
            "status": "new",
            "last_error_code": None,
            "last_error_message": None,
            "created_at": now,
            "updated_at": now
        }
        videos.append(vid)
    else:
        # Always store original source_url for traceability (overwrite with last provided)
        vid["source_url"] = url
        vid["updated_at"] = now

    # "Resolve/ingest" minimal metadata: infer extractor and platform id when possible
    # If we can't resolve any extractor at all, treat as NOT_FOUND per tool description.
    def _infer_extractor_and_id(curl):
        p = urllib.parse.urlparse(curl)
        host = p.netloc.lower()
        qs = dict(urllib.parse.parse_qsl(p.query, keep_blank_values=True))
        if "youtube.com" in host or "youtu.be" in host:
            # YouTube
            if "youtu.be" in host:
                video_id = (p.path or "").strip("/").split("/")[0] if p.path else None
            else:
                video_id = qs.get("v")
            if video_id and re.fullmatch(r"[A-Za-z0-9_-]{6,20}", video_id):
                return ("youtube", video_id, curl)
            return ("youtube", None, curl)
        if "vimeo.com" in host:
            m = re.search(r"/(\d+)", p.path or "")
            return ("vimeo", m.group(1) if m else None, curl)
        if host:
            return ("generic", None, curl)
        return (None, None, None)

    extractor, ex_vid, webpage = _infer_extractor_and_id(canonical_url)
    if extractor is None:
        vid["status"] = "error"
        vid["last_error_code"] = "UNRESOLVABLE_URL"
        vid["last_error_message"] = "Could not resolve extractor for URL."
        vid["updated_at"] = now
        _save("videos.json", videos)
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Video cannot be resolved/ingested from the URL.")

    # Fill metadata fields if missing
    if not vid.get("extractor"):
        vid["extractor"] = extractor
    if ex_vid and not vid.get("extractor_video_id"):
        vid["extractor_video_id"] = ex_vid
    if not vid.get("webpage_url"):
        vid["webpage_url"] = webpage

    # Ensure subtitle discovery has run if status is new or metadata_fetched
    if vid.get("status") in ("new", "metadata_fetched"):
        # "Refresh subtitle_tracks from extractor"
        # Offline implementation: deterministic synthetic track availability based on canonical_url hash.
        h = int(hashlib.sha256(canonical_url.encode("utf-8")).hexdigest(), 16)
        # Decide available languages deterministically
        base_langs = ["en", "es", "fr", "de", "pt", "it", "ja", "ko", "zh-Hant"]
        # Ensure at least one language
        n = 1 + (h % 4)  # 1..4 languages
        langs = []
        for i in range(len(base_langs)):
            idx = (h >> (i * 3)) % len(base_langs)
            lc = base_langs[idx]
            if lc not in langs:
                langs.append(lc)
            if len(langs) >= n:
                break

        # For each language, decide manual/auto and formats
        formats_pool = [["vtt", "srt"], ["vtt"], ["srt"], ["ttml", "vtt"], ["json3", "vtt"]]
        # Remove existing tracks for this video_id (refresh semantics)
        subtitle_tracks = [st for st in subtitle_tracks if not (isinstance(st, dict) and st.get("video_id") == vid["id"])]

        try:
            for i, lc in enumerate(langs):
                manual_avail = ((h >> (10 + i)) & 1) == 1
                auto_avail = True  # auto generally available in our offline model
                if manual_avail:
                    fmts = formats_pool[(h >> (20 + i * 2)) % len(formats_pool)]
                    st_id = "sub_" + hashlib.sha256(f"{vid['id']}|{lc}|0".encode("utf-8")).hexdigest()[:16]
                    subtitle_tracks.append({
                        "id": st_id,
                        "video_id": vid["id"],
                        "language_code": lc,
                        "is_auto_generated": False,
                        "track_name": f"{lc} (manual)",
                        "available_formats": list(dict.fromkeys(fmts)) if fmts else ["vtt"],
                        "source": "manual",
                        "discovered_at": now,
                        "created_at": now,
                        "updated_at": now
                    })
                if auto_avail:
                    fmts = formats_pool[(h >> (30 + i * 2)) % len(formats_pool)]
                    st_id = "sub_" + hashlib.sha256(f"{vid['id']}|{lc}|1".encode("utf-8")).hexdigest()[:16]
                    subtitle_tracks.append({
                        "id": st_id,
                        "video_id": vid["id"],
                        "language_code": lc,
                        "is_auto_generated": True,
                        "track_name": f"{lc} (auto-generated)",
                        "available_formats": list(dict.fromkeys(fmts)) if fmts else ["vtt"],
                        "source": "automatic",
                        "discovered_at": now,
                        "created_at": now,
                        "updated_at": now
                    })
            vid["status"] = "subtitles_fetched"
            vid["last_error_code"] = None
            vid["last_error_message"] = None
            vid["updated_at"] = now
        except Exception as e:
            vid["status"] = "error"
            vid["last_error_code"] = "SUBTITLE_DISCOVERY_FAILED"
            vid["last_error_message"] = str(e)
            vid["updated_at"] = now
            _save("videos.json", videos)
            _save("subtitle_tracks.json", subtitle_tracks)
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "No metadata can be fetched for this video.")

    _save("videos.json", videos)
    _save("subtitle_tracks.json", subtitle_tracks)

    # Read subtitle_tracks filtered by video_id and group by language
    tracks = [st for st in subtitle_tracks if isinstance(st, dict) and st.get("video_id") == vid["id"]]
    grouped = {}
    for st in tracks:
        lc = st.get("language_code")
        if not isinstance(lc, str) or not lc:
            continue
        if lc not in grouped:
            grouped[lc] = {"language_code": lc, "tracks": []}
        grouped[lc]["tracks"].append({
            "id": st.get("id"),
            "is_auto_generated": bool(st.get("is_auto_generated")),
            "track_name": st.get("track_name"),
            "available_formats": st.get("available_formats") if isinstance(st.get("available_formats"), list) else [],
            "source": st.get("source"),
            "discovered_at": st.get("discovered_at")
        })

    # Stable ordering
    languages = sorted(grouped.values(), key=lambda x: x["language_code"])

    _log("ok")
    return {
        "video": {
            "id": vid.get("id"),
            "canonical_url": vid.get("canonical_url"),
            "source_url": vid.get("source_url"),
            "extractor": vid.get("extractor"),
            "extractor_video_id": vid.get("extractor_video_id"),
            "status": vid.get("status"),
            "updated_at": vid.get("updated_at")
        },
        "languages": languages,
        "total_languages": len(languages)
    }

def download_video_subtitles(url, language=None, **_extra):
    import json, os, datetime, time, re, urllib.parse, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_credential_id=None, error_code=None):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{_now()}|download_video_subtitles|{random.random()}".encode("utf-8")).hexdigest()[:16],
            "endpoint": "download_video_subtitles",
            "credential_id": used_credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now()
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _is_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _canonicalize(u):
        p = urllib.parse.urlparse(u.strip())
        scheme = p.scheme.lower()
        netloc = p.netloc.lower()
        if netloc.endswith(":80") and scheme == "http":
            netloc = netloc[:-3]
        if netloc.endswith(":443") and scheme == "https":
            netloc = netloc[:-4]
        q = urllib.parse.parse_qsl(p.query, keep_blank_values=True)
        q.sort()
        query = urllib.parse.urlencode(q)
        path = re.sub(r"/{2,}", "/", p.path or "/")
        return urllib.parse.urlunparse((scheme, netloc, path, "", query, ""))

    def _valid_lang(code):
        if code is None:
            return True
        if not isinstance(code, str) or not code.strip():
            return False
        # loose BCP-47-ish: letters, digits, hyphen; start with letter; 2-20 chars total segments
        if len(code) > 35:
            return False
        return re.fullmatch(r"[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*", code.strip()) is not None

    if not _is_url(url):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `url` must be a valid http(s) URL.")
    if not _valid_lang(language):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `language` is malformed or unsupported.")

    canonical_url = _canonicalize(url)
    now = _now()

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    subtitle_tracks = _load("subtitle_tracks.json")
    if not isinstance(subtitle_tracks, list):
        subtitle_tracks = []
    prefs = _load("subtitle_download_preferences.json")
    if not isinstance(prefs, list):
        prefs = []
    jobs = _load("download_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # Upsert video
    vid = None
    for v in videos:
        if isinstance(v, dict) and v.get("canonical_url") == canonical_url:
            vid = v
            break
    if vid is None:
        vid_id = "vid_" + hashlib.sha256(f"{canonical_url}".encode("utf-8")).hexdigest()[:16]
        vid = {
            "id": vid_id,
            "source_url": url,
            "canonical_url": canonical_url,
            "extractor": "generic",
            "extractor_video_id": None,
            "title": None,
            "duration_seconds": None,
            "webpage_url": canonical_url,
            "status": "new",
            "last_error_code": None,
            "last_error_message": None,
            "created_at": now,
            "updated_at": now
        }
        videos.append(vid)
    else:
        vid["source_url"] = url
        vid["updated_at"] = now

    # Ensure subtitle discovery has run (reuse logic: if no tracks present, synthesize)
    if vid.get("status") in ("new", "metadata_fetched") or not any(isinstance(st, dict) and st.get("video_id") == vid["id"] for st in subtitle_tracks):
        # synthesize deterministic tracks
        h = int(hashlib.sha256(canonical_url.encode("utf-8")).hexdigest(), 16)
        base_langs = ["en", "es", "fr", "de", "pt", "it", "ja", "ko", "zh-Hant"]
        n = 1 + (h % 4)
        langs = []
        for i in range(len(base_langs)):
            idx = (h >> (i * 3)) % len(base_langs)
            lc = base_langs[idx]
            if lc not in langs:
                langs.append(lc)
            if len(langs) >= n:
                break
        formats_pool = [["vtt", "srt"], ["vtt"], ["srt"], ["ttml", "vtt"], ["json3", "vtt"]]
        subtitle_tracks = [st for st in subtitle_tracks if not (isinstance(st, dict) and st.get("video_id") == vid["id"])]
        try:
            for i, lc in enumerate(langs):
                manual_avail = ((h >> (10 + i)) & 1) == 1
                auto_avail = True
                if manual_avail:
                    fmts = formats_pool[(h >> (20 + i * 2)) % len(formats_pool)]
                    st_id = "sub_" + hashlib.sha256(f"{vid['id']}|{lc}|0".encode("utf-8")).hexdigest()[:16]
                    subtitle_tracks.append({
                        "id": st_id,
                        "video_id": vid["id"],
                        "language_code": lc,
                        "is_auto_generated": False,
                        "track_name": f"{lc} (manual)",
                        "available_formats": list(dict.fromkeys(fmts)) if fmts else ["vtt"],
                        "source": "manual",
                        "discovered_at": now,
                        "created_at": now,
                        "updated_at": now
                    })
                if auto_avail:
                    fmts = formats_pool[(h >> (30 + i * 2)) % len(formats_pool)]
                    st_id = "sub_" + hashlib.sha256(f"{vid['id']}|{lc}|1".encode("utf-8")).hexdigest()[:16]
                    subtitle_tracks.append({
                        "id": st_id,
                        "video_id": vid["id"],
                        "language_code": lc,
                        "is_auto_generated": True,
                        "track_name": f"{lc} (auto-generated)",
                        "available_formats": list(dict.fromkeys(fmts)) if fmts else ["vtt"],
                        "source": "automatic",
                        "discovered_at": now,
                        "created_at": now,
                        "updated_at": now
                    })
            vid["status"] = "subtitles_fetched"
            vid["last_error_code"] = None
            vid["last_error_message"] = None
            vid["updated_at"] = now
        except Exception as e:
            vid["status"] = "error"
            vid["last_error_code"] = "SUBTITLE_DISCOVERY_FAILED"
            vid["last_error_message"] = str(e)
            vid["updated_at"] = now
            _save("videos.json", videos)
            _save("subtitle_tracks.json", subtitle_tracks)
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Video cannot be resolved or subtitles cannot be discovered.")

    tracks = [st for st in subtitle_tracks if isinstance(st, dict) and st.get("video_id") == vid["id"]]

    if not tracks:
        _save("videos.json", videos)
        _save("subtitle_tracks.json", subtitle_tracks)
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No subtitles available for this video.")

    # Language selection rules when omitted
    selected_language = language.strip() if isinstance(language, str) else None
    if selected_language is None:
        # preference row for this video: pick a language with a preference if present; otherwise default 'en' if available else first available
        pref_langs = [p.get("language_code") for p in prefs if isinstance(p, dict) and p.get("video_id") == vid["id"] and isinstance(p.get("language_code"), str)]
        available_langs = sorted({st.get("language_code") for st in tracks if isinstance(st.get("language_code"), str)})
        chosen = None
        for pl in pref_langs:
            if pl in available_langs:
                chosen = pl
                break
        if chosen is None:
            chosen = "en" if "en" in available_langs else (available_langs[0] if available_langs else None)
        selected_language = chosen

    if not isinstance(selected_language, str) or not selected_language:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No suitable subtitle language could be selected.")

    # At most one queued/running matching job; reuse
    def _job_key(j):
        return (
            j.get("video_id"),
            j.get("job_type"),
            j.get("requested_resolution"),
            j.get("requested_language")
        )

    existing = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("video_id") != vid["id"]:
            continue
        if j.get("job_type") != "subtitles":
            continue
        if j.get("requested_resolution") is not None:
            continue
        if j.get("requested_language") != selected_language:
            continue
        if j.get("status") in ("queued", "running"):
            existing = j
            break
    if existing is not None:
        job_id = existing.get("id")
        job_artifacts = [a for a in artifacts if isinstance(a, dict) and a.get("job_id") == job_id and a.get("status") == "available"]
        _save("videos.json", videos)
        _save("subtitle_tracks.json", subtitle_tracks)
        _log("ok")
        return {
            "job": existing,
            "artifacts": job_artifacts
        }

    # Validate that requested_language exists at least as manual or auto; we still create job even if only auto (fallback true)
    lang_tracks = [st for st in tracks if st.get("language_code") == selected_language]
    if not lang_tracks:
        _save("videos.json", videos)
        _save("subtitle_tracks.json", subtitle_tracks)
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Requested subtitle language is not available for this video.")

    # Create job
    job_id = "job_" + hashlib.sha256(f"{vid['id']}|subtitles|{selected_language}|{random.random()}|{now}".encode("utf-8")).hexdigest()[:16]
    job = {
        "id": job_id,
        "video_id": vid["id"],
        "job_type": "subtitles",
        "requested_resolution": None,
        "requested_language": selected_language,
        "subtitle_fallback_to_auto": True,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "runner_host": None,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    _save("videos.json", videos)
    _save("subtitle_tracks.json", subtitle_tracks)
    _save("download_jobs.json", jobs)

    # Return job with any artifacts (likely none yet)
    job_artifacts = [a for a in artifacts if isinstance(a, dict) and a.get("job_id") == job_id and a.get("status") == "available"]
    _log("ok")
    return {"job": job, "artifacts": job_artifacts}

def download_video(url, resolution=None, **_extra):
    import json, os, datetime, time, re, urllib.parse, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_credential_id=None, error_code=None):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{_now()}|download_video|{random.random()}".encode("utf-8")).hexdigest()[:16],
            "endpoint": "download_video",
            "credential_id": used_credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now()
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _is_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _canonicalize(u):
        p = urllib.parse.urlparse(u.strip())
        scheme = p.scheme.lower()
        netloc = p.netloc.lower()
        if netloc.endswith(":80") and scheme == "http":
            netloc = netloc[:-3]
        if netloc.endswith(":443") and scheme == "https":
            netloc = netloc[:-4]
        q = urllib.parse.parse_qsl(p.query, keep_blank_values=True)
        q.sort()
        query = urllib.parse.urlencode(q)
        path = re.sub(r"/{2,}", "/", p.path or "/")
        return urllib.parse.urlunparse((scheme, netloc, path, "", query, ""))

    if not _is_url(url):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `url` must be a valid http(s) URL.")

    allowed = {"480p", "720p", "1080p", "best"}
    if resolution is None:
        resolution = "720p"
    if not isinstance(resolution, str) or resolution not in allowed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Parameter `resolution` must be one of: 480p, 720p, 1080p, best.")

    canonical_url = _canonicalize(url)
    now = _now()

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    jobs = _load("download_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # Upsert video by canonical_url
    vid = None
    for v in videos:
        if isinstance(v, dict) and v.get("canonical_url") == canonical_url:
            vid = v
            break
    if vid is None:
        vid_id = "vid_" + hashlib.sha256(f"{canonical_url}".encode("utf-8")).hexdigest()[:16]
        vid = {
            "id": vid_id,
            "source_url": url,
            "canonical_url": canonical_url,
            "extractor": "generic",
            "extractor_video_id": None,
            "title": None,
            "duration_seconds": None,
            "webpage_url": canonical_url,
            "status": "metadata_fetched",
            "last_error_code": None,
            "last_error_message": None,
            "created_at": now,
            "updated_at": now
        }
        videos.append(vid)
    else:
        vid["source_url"] = url
        if vid.get("status") == "new":
            vid["status"] = "metadata_fetched"
        vid["updated_at"] = now

    # Minimal "not found" heuristic: reject clearly non-video urls
    if any(bad in urllib.parse.urlparse(canonical_url).netloc.lower() for bad in ("localhost",)) and "/watch" not in canonical_url and "youtu" not in canonical_url:
        vid["status"] = "error"
        vid["last_error_code"] = "UNRESOLVABLE_URL"
        vid["last_error_message"] = "Video cannot be resolved."
        vid["updated_at"] = now
        _save("videos.json", videos)
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Video cannot be resolved or no downloadable video formats are available.")

    # Reuse queued/running matching job
    existing = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("video_id") != vid["id"]:
            continue
        if j.get("job_type") != "video":
            continue
        if j.get("requested_resolution") != resolution:
            continue
        if j.get("requested_language") is not None:
            continue
        if j.get("status") in ("queued", "running"):
            existing = j
            break
    if existing is not None:
        job_id = existing.get("id")
        job_artifacts = [a for a in artifacts if isinstance(a, dict) and a.get("job_id") == job_id and a.get("status") == "available"]
        _save("videos.json", videos)
        _log("ok")
        return {"job": existing, "artifacts": job_artifacts}

    # Create job
    job_id = "job_" + hashlib.sha256(f"{vid['id']}|video|{resolution}|{random.random()}|{now}".encode("utf-8")).hexdigest()[:16]
    job = {
        "id": job_id,
        "video_id": vid["id"],
        "job_type": "video",
        "requested_resolution": resolution,
        "requested_language": None,
        "subtitle_fallback_to_auto": False,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "runner_host": None,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    _save("videos.json", videos)
    _save("download_jobs.json", jobs)

    job_artifacts = [a for a in artifacts if isinstance(a, dict) and a.get("job_id") == job_id and a.get("status") == "available"]
    _log("ok")
    return {"job": job, "artifacts": job_artifacts}

