def download_transcript(url, language=None, **_extra):
    import json, os, datetime, time, re, urllib.parse, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "download_transcript"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_limits():
        cfg = _load("service_config.json")
        rl, dq = 120, 2000
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute", rl)
            dq = cfg.get("daily_quota", dq)
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            rl = cfg[0].get("rate_limit_per_minute", rl)
            dq = cfg[0].get("daily_quota", dq)
        return rl, dq

    def _check_limits(credential_value):
        rl_per_min, daily_quota = _get_limits()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        recent = 0
        daily = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential_value:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1
        if recent >= int(rl_per_min):
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if daily >= int(daily_quota):
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _log(status, credential_value=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential_value,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        })
        _save("request_logs.json", logs)

    # No explicit auth parameter => ambient; use a shared credential bucket.
    credential_value = "ambient"

    # Enforce quota/rate limit (observable dynamics)
    lim_err = _check_limits(credential_value)
    if lim_err:
        _log("error", credential_value, lim_err["error"]["code"])
        return lim_err

    # --------- validate inputs ---------
    if not isinstance(url, str) or not url.strip():
        _log("error", credential_value, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url must be a non-empty string", field="url")

    if language is None:
        language = "en"
    if not isinstance(language, str) or not language.strip():
        _log("error", credential_value, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language must be a non-empty string", field="language")
    language = language.strip()
    if len(language) > 32 or not re.match(r"^[A-Za-z]{2,3}([_-][A-Za-z0-9]{2,8})*$", language):
        _log("error", credential_value, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language is malformed", field="language")

    # --------- canonicalize URL and upsert video (rule) ---------
    def _canonicalize(u):
        u = u.strip()
        p = urllib.parse.urlsplit(u)
        if not p.scheme or not p.netloc:
            return None
        scheme = p.scheme.lower()
        host = p.netloc.lower().split("@")[-1].split(":")[0]
        path = p.path or "/"

        # Common canonicalization: drop fragments and most tracking params.
        q = urllib.parse.parse_qsl(p.query, keep_blank_values=True)
        keep = []
        host_l = host.lower()

        if "youtube.com" in host_l or host_l == "youtu.be":
            # Canonicalize YouTube by v when present; keep list? typically no.
            vid = None
            if host_l == "youtu.be":
                vid = path.strip("/").split("/")[0] if path.strip("/") else None
            for k, v in q:
                if k == "v" and v:
                    vid = v
            if vid:
                return f"https://www.youtube.com/watch?v={vid}"
            # fallback generic canonical
            keep = [(k, v) for (k, v) in q if k in ("v", "list", "index")]

        elif "vimeo.com" in host_l:
            # keep path only
            keep = []

        else:
            # keep non-tracking params
            tracking_prefixes = ("utm_", "fbclid", "gclid", "mc_cid", "mc_eid")
            for k, v in q:
                lk = k.lower()
                if lk.startswith("utm_") or lk in tracking_prefixes:
                    continue
                keep.append((k, v))

        query = urllib.parse.urlencode(keep, doseq=True)
        return urllib.parse.urlunsplit((scheme, host, path, query, ""))

    canonical_url = _canonicalize(url)
    if not canonical_url:
        _log("error", credential_value, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url is invalid", field="url")

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    now_ts = _now()

    video = None
    for r in videos:
        if isinstance(r, dict) and r.get("canonical_url") == canonical_url:
            video = r
            break

    if video is None:
        # generate id similar to existing: vid_<ULID-ish>. We'll use time+random.
        vid_id = "vid_" + secrets.token_hex(13)
        video = {
            "id": vid_id,
            "source_url": url,
            "canonical_url": canonical_url,
            "extractor": None,
            "extractor_video_id": None,
            "title": None,
            "duration_seconds": None,
            "webpage_url": None,
            "status": "new",
            "last_error_code": None,
            "last_error_message": None,
            "created_at": now_ts,
            "updated_at": now_ts,
        }
        videos.append(video)
        _save("videos.json", videos)
    else:
        # Always store most-recent source_url for traceability
        video["source_url"] = url
        video["updated_at"] = now_ts
        _save("videos.json", videos)

    video_id = video.get("id")

    # --------- ensure subtitle discovery has run (minimal offline behavior) ---------
    # Real system would call extractor; offline we can only rely on existing tracks.
    # If status indicates not fetched, attempt a "refresh" by updating discovered_at
    # for existing tracks; if none exist, set error.
    subtitle_tracks = _load("subtitle_tracks.json")
    if not isinstance(subtitle_tracks, list):
        subtitle_tracks = []
    tracks_for_video = [t for t in subtitle_tracks if isinstance(t, dict) and t.get("video_id") == video_id]

    if video.get("status") in ("new", "metadata_fetched"):
        if tracks_for_video:
            # Refresh timestamps to represent discovery run
            for t in tracks_for_video:
                t["discovered_at"] = now_ts
                t["updated_at"] = now_ts
            video["status"] = "subtitles_fetched"
            video["last_error_code"] = None
            video["last_error_message"] = None
            video["updated_at"] = now_ts
            _save("subtitle_tracks.json", subtitle_tracks)
            _save("videos.json", videos)
        else:
            # No tracks in datastore; mark error per rule "or 'error' on failure"
            video["status"] = "error"
            video["last_error_code"] = "NO_SUBTITLES_DISCOVERED"
            video["last_error_message"] = "Subtitle discovery did not find any tracks for this video."
            video["updated_at"] = now_ts
            _save("videos.json", videos)
            _log("error", credential_value, "NOT_FOUND")
            return _err("NOT_FOUND", "No subtitle tracks available for this video", video_id=video_id)

    # Re-read tracks_for_video in case we refreshed
    subtitle_tracks = _load("subtitle_tracks.json")
    if not isinstance(subtitle_tracks, list):
        subtitle_tracks = []
    tracks_for_video = [t for t in subtitle_tracks if isinstance(t, dict) and t.get("video_id") == video_id]

    # --------- Select language: requested language must exist or NOT_FOUND ---------
    # Relax: allow language codes even if not present in preferences; only require tracks exist.
    lang_norm = language.replace("_", "-")
    def _lang_match(tlang):
        if not isinstance(tlang, str):
            return False
        tl = tlang.replace("_", "-")
        return tl.lower() == lang_norm.lower()

    tracks_for_lang = [t for t in tracks_for_video if _lang_match(t.get("language_code"))]
    if not tracks_for_lang:
        # Do not fail due to picking wrong context; here context is the datastore itself.
        _log("error", credential_value, "NOT_FOUND")
        return _err("NOT_FOUND", "No subtitle track available for requested language", video_id=video_id, language=language)

    # --------- create/reuse transcript job (dedupe rule) ---------
    jobs = _load("download_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # At most one running job per tuple; also reuse queued/running
    def _job_key(j):
        return (
            j.get("video_id"),
            j.get("job_type"),
            j.get("requested_resolution"),
            j.get("requested_language"),
        )

    wanted_key = (video_id, "transcript", None, language)
    existing = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if _job_key(j) == wanted_key and j.get("status") in ("queued", "running"):
            existing = j
            break
        # Idempotency: if a succeeded job exists for same request, return it.
        if _job_key(j) == wanted_key and j.get("status") == "succeeded":
            existing = j
            break

    if existing is None:
        job_id = "job_" + secrets.token_hex(13)
        job = {
            "id": job_id,
            "video_id": video_id,
            "job_type": "transcript",
            "requested_resolution": None,
            "requested_language": language,
            "subtitle_fallback_to_auto": True,
            "status": "queued",
            "attempt_count": 0,
            "max_attempts": 3,
            "runner_host": None,
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "created_at": now_ts,
            "updated_at": now_ts,
        }
        jobs.append(job)
        _save("download_jobs.json", jobs)
        existing = job

    # --------- attach resulting transcript artifact reference (if already exists) ---------
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    transcript_artifact = None
    for a in artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("job_id") == existing.get("id") and a.get("artifact_type") == "transcript_text" and a.get("status") == "available":
            transcript_artifact = a
            break

    resp = {
        "job": existing,
        "artifact": transcript_artifact
    }
    _log("ok", credential_value, None)
    return resp

