    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_video"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # validate
    if not isinstance(video_id, str) or not video_id.strip():
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "video_id must be a non-empty string", field="video_id")
    if not isinstance(auth_token, str) or not auth_token.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string", field="auth_token")

    # authenticate token against datastore if present; else accept any (no auth store provided)
    tokens = _load("auth_tokens.json")
    if isinstance(tokens, list) and tokens:
        ok = False
        for t in tokens:
            if isinstance(t, dict) and (t.get("token") == auth_token or t.get("id") == auth_token) and t.get("status", "active") == "active":
                ok = True
                break
        if not ok:
            _log("error", auth_token, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid credentials")

    videos = _load("videos.json")
