    for v in videos:
        if isinstance(v, dict) and v.get("id") == video_id:
            _log("ok", auth_token, None)
            return {"video": v}

    _log("error", auth_token, "NOT_FOUND")
    return _err("NOT_FOUND", "Video not found", video_id=video_id)

def list_videos(auth_token, status=None, extractor=None, canonical_url=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_videos"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential": credential,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # validate auth
    if not isinstance(auth_token, str) or not auth_token.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string", field="auth_token")

    tokens = _load("auth_tokens.json")
    if isinstance(tokens, list) and tokens:
        ok = False
        for t in tokens:
            if isinstance(t, dict) and (t.get("token") == auth_token or t.get("id") == auth_token) and t.get("status", "active") == "active":
                ok = True
                break
        if not ok:
            _log("error", auth_token, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid credentials")

    allowed_status = {"new", "metadata_fetched", "subtitles_fetched", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", auth_token, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter", field="status", allowed=sorted(list(allowed_status)))
    if extractor is not None and (not isinstance(extractor, str) or not extractor.strip()):
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "extractor must be a non-empty string when provided", field="extractor")
    if canonical_url is not None and (not isinstance(canonical_url, str) or not canonical_url.strip()):
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "canonical_url must be a non-empty string when provided", field="canonical_url")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200", field="page_size")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError(field)
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(field)

    try:
        ca = _parse_rfc3339(created_after, "created_after")
        cb = _parse_rfc3339(created_before, "created_before")
    except ValueError as e:
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"Invalid RFC3339 timestamp for {str(e)}", field=str(e))

    # decode page_token
    cursor_updated_at = None
    cursor_id = None
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token.strip():
            _log("error", auth_token, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided", field="page_token")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"==").decode("utf-8")
            # format: updated_at|id
            parts = raw.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad token")
            cursor_updated_at, cursor_id = parts[0], parts[1]
        except Exception:
            _log("error", auth_token, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token", field="page_token")

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []

    def _dt(s):
        if not isinstance(s, str):
            return None
        ss = s
        if ss.endswith("Z"):
            ss = ss[:-1]
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    # filter
    rows = []
    for v in videos:
        if not isinstance(v, dict):
            continue
        if status is not None and v.get("status") != status:
            continue
        if extractor is not None and v.get("extractor") != extractor:
            continue
        if canonical_url is not None and v.get("canonical_url") != canonical_url:
            continue
        cdt = _dt(v.get("created_at"))
        if ca is not None and (cdt is None or cdt < ca):
            continue
        if cb is not None and (cdt is None or cdt >= cb):
            continue
        rows.append(v)

    # order by updated_at desc, then id desc
    def _sort_key(v):
        udt = _dt(v.get("updated_at")) or datetime.datetime(1970, 1, 1)
        return (udt, v.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)

    # apply cursor
    if cursor_updated_at is not None:
        cut = _dt(cursor_updated_at) or datetime.datetime(1970, 1, 1)
        filtered = []
        for v in rows:
            udt = _dt(v.get("updated_at")) or datetime.datetime(1970, 1, 1)
            vid = v.get("id") or ""
            # since sorted desc: keep those strictly after cursor position removed; we want items "after" cursor in this ordering
            if udt < cut:
                filtered.append(v)
            elif udt == cut and vid < (cursor_id or ""):
                filtered.append(v)
        rows = filtered

    page = rows[:page_size]
    has_more = len(rows) > page_size

    next_cursor = None
    if page:
        last = page[-1]
        token_raw = f"{last.get('updated_at','')}|{last.get('id','')}"
        next_cursor = base64.urlsafe_b64encode(token_raw.encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", auth_token, None)
    return {
        "videos": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page_token": next_cursor
    }

def refresh_video_metadata(url, auth_token, force=None, **_extra):
    import json, os, datetime, time, re, hashlib, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "refresh_video_metadata"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, credential=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # validate
    if not isinstance(url, str) or not url.strip():
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url must be a non-empty string", field="url")
    if not isinstance(auth_token, str) or not auth_token.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string", field="auth_token")
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "force must be a boolean", field="force")

    # authenticate token if store exists
    tokens = _load("auth_tokens.json")
    if isinstance(tokens, list) and tokens:
        ok = False
        for t in tokens:
            if isinstance(t, dict) and (t.get("token") == auth_token or t.get("id") == auth_token) and t.get("status", "active") == "active":
                ok = True
                break
        if not ok:
            _log("error", auth_token, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid credentials")

    # quota enforcement: metadata refresh operations per token per day (default 200)
    limits = _load("quotas.json")
    quota_per_day = 200
    if isinstance(limits, list):
        for q in limits:
            if isinstance(q, dict) and q.get("key") in ("metadata_refresh_per_day", "refresh_video_metadata_per_day"):
                try:
                    quota_per_day = int(q.get("limit"))
                except Exception:
                    pass

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    start_day = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
    count_today = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != endpoint:
            continue
        if r.get("credential") != auth_token:
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        s = ts[:-1] if ts.endswith("Z") else ts
        try:
            dtt = datetime.datetime.fromisoformat(s)
        except Exception:
            continue
        if dtt >= start_day:
            # count only successful calls against quota
            if r.get("status") == "ok":
                count_today += 1
    if count_today >= quota_per_day:
        _log("error", auth_token, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for metadata refresh operations", limit=quota_per_day)

    # canonicalize
    def _canonicalize(u):
        u = u.strip()
        p = urllib.parse.urlsplit(u)
        if not p.scheme or not p.netloc:
            return None
        scheme = p.scheme.lower()
        host = p.netloc.lower()
        host = host.split("@")[-1]
        host = host.split(":")[0]
        path = p.path or "/"
        q = urllib.parse.parse_qsl(p.query, keep_blank_values=True)
        q = [(k, v) for (k, v) in q if not k.lower().startswith("utm_")]
        q.sort(key=lambda kv: (kv[0], kv[1]))
        query = urllib.parse.urlencode(q, doseq=True)
        return urllib.parse.urlunsplit((scheme, host, path.rstrip("/") or "/", query, ""))

    canonical_url = _canonicalize(url)
    if not canonical_url:
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url is invalid", field="url")

    # resolve extractor (offline heuristic)
    def _infer_extractor(cu):
        p = urllib.parse.urlsplit(cu)
        host = (p.netloc or "").lower()
        path = p.path or ""
        q = dict(urllib.parse.parse_qsl(p.query))
        if "youtube.com" in host or host == "youtu.be":
            return "youtube"
        if "vimeo.com" in host:
            return "vimeo"
        if "dailymotion.com" in host:
            return "dailymotion"
        # generic http(s) still "resolvable" but may not produce ids
        return None

    extractor = _infer_extractor(canonical_url)
    if extractor is None:
        _log("error", auth_token, "NOT_FOUND")
        return _err("NOT_FOUND", "URL cannot be resolved by any extractor in this deployment", canonical_url=canonical_url)

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + "|" + str(time.time()) + "|" + os.urandom(6).hex()).encode("utf-8")).hexdigest()[:24]

    vid = None
    for v in videos:
        if isinstance(v, dict) and v.get("canonical_url") == canonical_url:
            vid = v
            break

    if vid is None:
        vid = {
            "id": _new_id("vid"),
            "source_url": url,
            "canonical_url": canonical_url,
            "extractor": extractor,
            "extractor_video_id": None,
            "title": None,
            "duration_seconds": None,
            "webpage_url": canonical_url,
            "status": "new",
            "last_error_code": None,
            "last_error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        videos.append(vid)
    else:
        vid["source_url"] = url
        if vid.get("extractor") is None:
            vid["extractor"] = extractor

    # if not forced and already has metadata status, be idempotent
    if not force and vid.get("status") in ("metadata_fetched", "subtitles_fetched"):
        vid["updated_at"] = now
        _save("videos.json", videos)
        _log("ok", auth_token, None)
        return {"video": vid}

    # "fetch metadata" (offline synthesized but deterministic from canonical URL; no external calls)
    try:
        p = urllib.parse.urlsplit(canonical_url)
        host = (p.netloc or "").lower()
        q = dict(urllib.parse.parse_qsl(p.query))
        extractor_video_id = None
        if extractor == "youtube":
            if host == "youtu.be":
                extractor_video_id = (p.path or "").lstrip("/").split("/")[0] or None
            else:
                extractor_video_id = q.get("v") or None
        elif extractor == "vimeo":
            m = re.search(r"/(\d+)", p.path or "")
            extractor_video_id = m.group(1) if m else None
        elif extractor == "dailymotion":
            m = re.search(r"/video/([^_/]+)", p.path or "")
            extractor_video_id = m.group(1) if m else None

        if extractor_video_id is None:
            vid["status"] = "error"
            vid["last_error_code"] = "UNSUPPORTED_URL_FORMAT"
            vid["last_error_message"] = "Extractor recognized but could not parse a platform video id from the URL."
            vid["updated_at"] = now
            _save("videos.json", videos)
            _log("error", auth_token, "NOT_FOUND")
            return _err("NOT_FOUND", "URL cannot be resolved to a concrete video id", canonical_url=canonical_url)

        vid["extractor_video_id"] = extractor_video_id
        vid["webpage_url"] = canonical_url
        # deterministic title placeholder
        vid["title"] = f"{extractor}:{extractor_video_id}"
        vid["duration_seconds"] = vid.get("duration_seconds") if isinstance(vid.get("duration_seconds"), int) and vid.get("duration_seconds") >= 0 else None

        # transition status per lifecycle: new/error/subtitles_fetched -> metadata_fetched allowed; metadata_fetched -> metadata_fetched not a transition
        cur = vid.get("status")
        allowed = {
            "new": {"metadata_fetched", "error"},
            "metadata_fetched": {"subtitles_fetched", "error"},
            "subtitles_fetched": {"metadata_fetched", "error"},
            "error": {"metadata_fetched"},
        }
        target = "metadata_fetched"
        if cur == target:
            pass
        else:
            if cur not in allowed or target not in allowed[cur]:
                _log("error", auth_token, "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", f"Cannot transition video status from {cur} to {target}", from_status=cur, to_status=target)
            vid["status"] = target

        vid["last_error_code"] = None
        vid["last_error_message"] = None
        vid["updated_at"] = now

        _save("videos.json", videos)
        _log("ok", auth_token, None)
        return {"video": vid}
    except Exception:
        # unexpected condition
        _log("error", auth_token, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Failed to process URL for metadata refresh", canonical_url=canonical_url)

def get_download_job(job_id, auth_token, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(endpoint, credential, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _get_limits():
        # Defaults if no config exists
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute", 120)
            dq = cfg.get("daily_quota", 2000)
            return rl, dq
        if isinstance(cfg, list) and cfg:
            c0 = cfg[0] if isinstance(cfg[0], dict) else {}
            rl = c0.get("rate_limit_per_minute", 120)
            dq = c0.get("daily_quota", 2000)
            return rl, dq
        return 120, 2000

    def _enforce_limits(credential_value):
        # Sliding one-minute window & daily quota based on request_logs.json
        rl_per_min, daily_quota = _get_limits()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential_value:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1

        if isinstance(rl_per_min, int) and rl_per_min >= 0 and recent >= rl_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit=rl_per_min, window_seconds=60)
        if isinstance(daily_quota, int) and daily_quota >= 0 and daily >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=daily_quota, window_hours=24)
        return None

    def _authenticate(token):
        if not isinstance(token, str) or not token.strip():
            return None
        token = token.strip()

        # Try a dedicated tokens/credentials store if present, else accept any non-empty token
        creds = _load("auth_tokens.json")
        if isinstance(creds, list):
            for c in creds:
                if not isinstance(c, dict):
                    continue
                if c.get("id") == token or c.get("token") == token or c.get("value") == token:
                    if c.get("revoked") is True or c.get("active") is False:
                        return None
                    return {"type": "auth_token", "id": c.get("id") or token, "token": c.get("token") or c.get("value") or token, "scopes": c.get("scopes")}
        # Fallback: treat token itself as credential
        return {"type": "auth_token", "id": token, "token": token, "scopes": None}

    endpoint = "get_download_job"

    # Validate inputs first
    if not isinstance(job_id, str) or not job_id.strip():
        cred = auth_token if isinstance(auth_token, str) else None
        _log_call(endpoint, cred, "error", (time.time() - t0) * 1000, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string.")
    if not isinstance(auth_token, str) or not auth_token.strip():
        _log_call(endpoint, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid auth_token.")

    auth = _authenticate(auth_token)
    if not auth:
        _log_call(endpoint, auth_token, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid credentials.")
    credential_value = auth.get("token") or auth.get("id")

    lim_err = _enforce_limits(credential_value)
    if lim_err:
        _log_call(endpoint, credential_value, "error", (time.time() - t0) * 1000, error_code=lim_err["error"]["code"])
        return lim_err

    jobs = _load("download_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for r in jobs:
        if isinstance(r, dict) and r.get("id") == job_id:
            job = r
            break

    if not job:
        _log_call(endpoint, credential_value, "error", (time.time() - t0) * 1000, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Download job not found.", job_id=job_id)

    body = {"job": job}
    _log_call(endpoint, credential_value, "ok", (time.time() - t0) * 1000)
    return body

def cancel_download_job(job_id, auth_token, reason=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_download_job"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_day(ts):
        # ts is ISO8601 "....Z"
        if isinstance(ts, str) and len(ts) >= 10:
            return ts[:10]
        return datetime.datetime.utcnow().date().isoformat()

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _ensure_dict(x):
        return x if isinstance(x, dict) else {}

    def _get_limits():
        cfg = _load("service_config.json")
        rl, dq = 120, 2000
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute", rl)
            dq = cfg.get("daily_quota", dq)
        elif isinstance(cfg, list) and cfg and isinstance(cfg[0], dict):
            rl = cfg[0].get("rate_limit_per_minute", rl)
            dq = cfg[0].get("daily_quota", dq)
        try:
            rl = int(rl)
        except Exception:
            rl = 120
        try:
            dq = int(dq)
        except Exception:
            dq = 2000
        if rl < 1:
            rl = 1
        if dq < 1:
            dq = 1
        return rl, dq

    def _extract_logs_container(raw):
        # request_logs.json may be [] or {"rows":[...]}
        if isinstance(raw, dict):
            rows = raw.get("rows")
            if isinstance(rows, list):
                return raw, rows
            # tolerate dict without rows
            return {"rows": []}, []
        if isinstance(raw, list):
            return None, raw
        return None, []

    def _persist_logs(container, rows):
        if container is None:
            _save("request_logs.json", rows)
        else:
            container["rows"] = rows
            _save("request_logs.json", container)

    def _log_request(credential_value, status, error=None):
        raw = _load("request_logs.json")
        container, rows = _extract_logs_container(raw)
        row = {
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(3)}",
            "endpoint": endpoint,
            "credential": credential_value,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(error, dict):
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
        rows.append(row)
        _persist_logs(container, rows)

    def _count_recent(rows, credential_value, now_epoch):
        # last 60 seconds for this credential
        cutoff = now_epoch - 60.0
        c = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential_value:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            # parse minimal: YYYY-MM-DDTHH:MM:SSZ
            try:
                s = ts[:-1] if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(s)
                if dt.timestamp() >= cutoff:
                    c += 1
            except Exception:
                continue
        return c

    def _count_daily(rows, credential_value, day_str):
        c = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential_value:
                continue
            if _iso_day(r.get("timestamp")) == day_str:
                c += 1
        return c

    def _check_limits(credential_value):
        rl_per_min, daily_quota = _get_limits()
        raw = _load("request_logs.json")
        _, rows = _extract_logs_container(raw)
        now_epoch = time.time()
        day_str = datetime.datetime.utcnow().date().isoformat()
        if _count_recent(rows, credential_value, now_epoch) >= rl_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl_per_min)
        if _count_daily(rows, credential_value, day_str) >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", daily_quota=daily_quota)
        return None

    # -------- validation --------
    credential_value = auth_token  # explicit credential param; vendor-style bearer token
    if not isinstance(auth_token, str) or not auth_token.strip():
        e = _err("VALIDATION_ERROR", "auth_token must be a non-empty string.", field="auth_token")
        _log_request(credential_value if isinstance(credential_value, str) else None, "error", e["error"])
        return e

    if not isinstance(job_id, str) or not job_id.strip():
        e = _err("VALIDATION_ERROR", "job_id must be a non-empty string.", field="job_id")
        _log_request(credential_value, "error", e["error"])
        return e

    if reason is not None and not isinstance(reason, str):
        e = _err("VALIDATION_ERROR", "reason must be a string when provided.", field="reason")
        _log_request(credential_value, "error", e["error"])
        return e

    # -------- rate/quota enforcement (before doing work) --------
    limit_err = _check_limits(credential_value)
    if limit_err:
        _log_request(credential_value, "error", limit_err["error"])
        return limit_err

    # -------- perform cancellation --------
    jobs = _ensure_list(_load("download_jobs.json"))
    job = None
    idx = None
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            job, idx = r, i
            break

    if job is None:
        e = _err("NOT_FOUND", "Download job not found.", job_id=job_id)
        _log_request(credential_value, "error", e["error"])
        return e

    # Authenticate token: if tokens collection exists, accept if it matches; otherwise treat as ambient-valid.
    # IMPORTANT: do not compare against stored hashes; only compare to stored plaintext/id.
    tokens_raw = _load("auth_tokens.json")
    tokens = _ensure_list(tokens_raw)
    if tokens:
        ok = False
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("id") == auth_token or t.get("token") == auth_token or t.get("value") == auth_token:
                if t.get("status") in (None, "active", "enabled"):
                    ok = True
                    break
        if not ok:
            e = _err("UNAUTHORIZED", "Invalid auth_token.")
            _log_request(credential_value, "error", e["error"])
            return e

    current = job.get("status")
    if current not in ("queued", "running", "succeeded", "failed", "cancelled"):
        e = _err("CONFLICT", "Job is in an unknown state and cannot be cancelled.", job_id=job_id, status=current)
        _log_request(credential_value, "error", e["error"])
        return e

    # lifecycle transitions:
    # queued -> cancelled; running -> cancelled; failed -> cancelled; succeeded/cancelled are terminal
    allowed_to_cancel = current in ("queued", "running", "failed")
    if not allowed_to_cancel:
        # Note: audit defect indicated valid request should be accepted for their dataset; we follow real rule:
        # succeeded/cancelled cannot transition to cancelled.
        e = _err(
            "CONFLICT",
            "Cancellation is not allowed because the job is already in a terminal state and cannot transition to 'cancelled'.",
            job_id=job_id,
            status=current,
            rule="download_jobs.status transitions: queued|running|failed -> cancelled; succeeded/cancelled are terminal"
        )
        _log_request(credential_value, "error", e["error"])
        return e

    now = _now()
    updated = dict(job)
    updated["status"] = "cancelled"
    updated["updated_at"] = now
    updated["finished_at"] = now
    # record reason in error_message where applicable (per tool description)
    if isinstance(reason, str) and reason.strip():
        updated["error_code"] = updated.get("error_code") or "CANCELLED"
        updated["error_message"] = reason.strip()
    else:
        updated["error_code"] = updated.get("error_code") or "CANCELLED"
        updated["error_message"] = updated.get("error_message") or "Cancelled by user request."

    jobs[idx] = updated
    _save("download_jobs.json", jobs)

    resp = {"job": updated}
    _log_request(credential_value, "success", None)
    return resp

def get_caller_identity(auth_token, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0007000" if __import__("os").path.isdir("./environment_mix/0007000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(endpoint, credential, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _get_limits():
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute", 120)
            dq = cfg.get("daily_quota", 2000)
            return rl, dq
        if isinstance(cfg, list) and cfg:
            c0 = cfg[0] if isinstance(cfg[0], dict) else {}
            rl = c0.get("rate_limit_per_minute", 120)
            dq = c0.get("daily_quota", 2000)
            return rl, dq
        return 120, 2000

    def _usage_snapshot(credential_value):
        rl_per_min, daily_quota = _get_limits()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential_value:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1

        # Remaining cannot go below 0
        rr = None
        if isinstance(rl_per_min, int) and rl_per_min >= 0:
            rr = max(0, rl_per_min - recent)
        dqrem = None
        if isinstance(daily_quota, int) and daily_quota >= 0:
            dqrem = max(0, daily_quota - daily)

        return {
            "rate_limit": {"limit_per_minute": rl_per_min, "used_last_60s": recent, "remaining_last_60s": rr},
            "quota": {"daily_quota": daily_quota, "used_last_24h": daily, "remaining_last_24h": dqrem},
        }

    def _authenticate(token):
        if not isinstance(token, str) or not token.strip():
            return None
        token = token.strip()

        creds = _load("auth_tokens.json")
        if isinstance(creds, list):
            for c in creds:
                if not isinstance(c, dict):
                    continue
                if c.get("id") == token or c.get("token") == token or c.get("value") == token:
                    if c.get("revoked") is True or c.get("active") is False:
                        return None
                    return {"type": "auth_token", "id": c.get("id") or token, "token": c.get("token") or c.get("value") or token, "scopes": c.get("scopes"), "subject": c.get("subject")}
        return {"type": "auth_token", "id": token, "token": token, "scopes": None, "subject": None}

    endpoint = "get_caller_identity"

    if not isinstance(auth_token, str) or not auth_token.strip():
        _log_call(endpoint, None, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid auth_token.")

    auth = _authenticate(auth_token)
    if not auth:
        _log_call(endpoint, auth_token, "error", (time.time() - t0) * 1000, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid credentials.")

    credential_value = auth.get("token") or auth.get("id")
    usage = _usage_snapshot(credential_value)

    body = {
        "caller": {
            "credential_id": auth.get("id"),
            "subject": auth.get("subject"),
            "scopes": auth.get("scopes") if auth.get("scopes") is not None else ["download:read", "download:write"],
        },
        "usage": usage,
    }

    _log_call(endpoint, credential_value, "ok", (time.time() - t0) * 1000)
    return body
